   299	      codePoint === undefined ||
   300	      codePoint === 0x3a ||
   301	      !(
   302	        codePoint === 0x21 ||
   303	        (codePoint >= 0x23 && codePoint <= 0x5b) ||
   304	        (codePoint >= 0x5d && codePoint <= 0x7e)
