15	    return { bytes: new Uint8Array(), ok: true };
16	  }
17	
18	  const reader = body.getReader();
19	  const chunks: Uint8Array[] = [];
20	  let totalBytes = 0;
21	
22	  try {
23	    for (;;) {
24	      const read = await reader.read();
25	
26	      if (read.done) {
27	        break;
28	      }
29	
30	      totalBytes += read.value.byteLength;
31	
32	      if (totalBytes > maxBytes) {
33	        void reader.cancel().catch(() => undefined);
34	        return { ok: false };
35	      }
36	
37	      chunks.push(read.value);
