 31	    return false;
 32	  }
 33	
 34	  let mismatch = 0;
 35	
 36	  for (let index = 0; index < left.length; index += 1) {
 37	    mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
 38	  }
 39	
 40	  return mismatch === 0;
 41	}
